contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 D, uint256 A) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (D)); require(D <= 1000000000000000000000000000000);
        require(address(this).balance >= D);
        require(D > 0 && D <= type(uint128).max);

        c.deposit{value: D}(); if (__ESBMC_reverted()) return;

        uint256 cBefore = address(c).balance;
        uint256 meBefore = address(this).balance;

        bool reverted;
        c.withdraw(A); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cAfter = address(c).balance;
        uint256 meAfter = address(this).balance;

        assert(reverted
            ? (A > D && cAfter == cBefore && meAfter == meBefore)
            : (A <= D && cAfter == cBefore - A && meAfter == meBefore + A));
    }
}

