pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 D, uint256 A) internal {
        D = bound(D, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= D);
        vm.assume(D > 0 && D <= type(uint128).max);
        try c.deposit{value: D}() {} catch { return; }
        uint256 cBefore = address(c).balance;
        uint256 meBefore = address(this).balance;
        bool reverted;
        try c.withdraw(A) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 cAfter = address(c).balance;
        uint256 meAfter = address(this).balance;
        assertTrue(reverted
            ? (A > D && cAfter == cBefore && meAfter == meBefore)
            : (A <= D && cAfter == cBefore - A && meAfter == meBefore + A));
    }

    function testFuzz_run(uint256 D, uint256 A) public {
        _run(D, A);
    }

    receive() external payable {}
}
